steps.text:
/*
	VIOC_war_replay.sqf - agregado por tools/vio_build.py (parche war_replay; copia configurada, no es del autor de la
	mision). Fuente: work/v6_build/war_replay/.

	"Historia de la guerra": el servidor graba como se domina el mapa y cualquier jugador la repite en el mapa, acelerada.
	init.sqf lo carga en todas las maquinas (call compile). Sin datos del mapa ni de la nacion: pueblos de CTI_Towns,
	bandos por su ID (0 oeste azul, 1 este rojo, 2 resistencia verde, otro gris), aerodromos de CfgWorlds >> worldName.

	SERVIDOR (graba, VIOC_WR_DATA en missionNamespace):
	  - Al estar los pueblos listos: lista de pueblos [nombre, x, y, duenio inicial, marcas (1 capital, 2 aerodromo)].
	  - Cada VIOC_WR_TICK s mira cti_town_sideID de cada pueblo (barato) y anota cada cambio de duenio [t, pueblo, bando].
	  - Cada VIOC_WR_SLOW s: HQ destruido, edificios de base perdidos, operaciones especiales lanzadas (ai_specops /
	    specops_player: VIOC_SO_OPS, VIOC_SO_PREQ) y A-10 / Ghostrider (air_support: VIOC_ASS_ACTIVE), si esos parches estan.
	    Capital o aerodromo tomados: aviso propio. Fin de la partida: aviso con el ganador.
	  - Cada VIOC_WR_SNAP0 s (120): foto de las posiciones de los jefes de los equipos de oeste y este (cti_teams), como
	    mucho VIOC_WR_MAX_TEAMS por bando y VIOC_WR_MAX_POS posiciones en total: al pasarse se borra una foto de cada dos y
	    se dobla el intervalo (hasta VIOC_WR_SNAP_MAX).
	  - Perfil del servidor (profileNamespace): clave "VIOC_WAR_<missionName>_<worldName>" = partida en curso (se copia en
	    cada foto); "<clave>_HIST" = las ultimas VIOC_WR_HIST_MAX partidas terminadas (o cortadas) con fecha (systemTime).
	    saveProfileNamespace: al terminar la partida, y cada VIOC_WR_SAVE_EVERY s solo si la mision no guarda sola
	    (con PERSIST activo la mision guarda cada CTI_SAVE_PERIODE y nuestro dato ya esta en el perfil).
	    Si la mision carga un guardado (PERSIST) y la partida grabada sin terminar es de los mismos pueblos, se continua.
	  - Formato (VIOCWR1): [ "VIOCWR1", meta, pueblos, cambios, avisos, fotos, estado ]
	      meta    = [missionName, worldName, worldSize, briefingName, systemTime al empezar, date al empezar,
	                 [nombre oeste, nombre este, nombre resistencia], version, unidad (10 m)]
	      pueblos = [[nombre, x, y, duenio inicial, marcas], ...]   (x, y en metros)
	      cambios = texto "t,pueblo,bando;..."                       (t = s de partida)
	      avisos  = texto "t,tipo,bando,x,y,dato;..."                (x, y en unidades de 10 m; tipo start, resume, cap,
	                af, hq, base (dato = edificios perdidos), so, cas, gs, end (bando = ganador); dato = pueblo o -1)
	      fotos   = texto "t,minuto del dia,OESTE,ESTE;..."          (OESTE/ESTE = "x y x y ..." en unidades de 10 m o "-")
	      estado  = [t final, terminada (0/1), ganador, systemTime final, date final, posiciones, cambios, avisos,
	                 marcas de recorte (1 avisos, 2 cambios, 4 fotos), intervalo de fotos]
	    Se exporta a HTML o GIF con work/v6_build/war_replay/war_replay.py (lee el .vars.Arma3Profile del anfitrion).
	  - Gancho en Server\FSM\update_victory.fsm (End_FSM, antes de avisar a los clientes): VIOC_WR_fnc_gameOver cierra y
	    guarda la partida. En servidor dedicado, con la repeticion al final activa, el endMission se retrasa
	    VIOC_WR_SPEED + 20 s (VIOC_WR_END_DELAY; nunca se queda sin terminar).

	CLIENTE (repite):
	  - Accion "Ver historia de la guerra" (Client_AddMissionActions): abre el mapa y repite la guerra en VIOC_WR_SPEED s
	    (botones 30 s / 60 s / 120 s, pausa, reiniciar, zonas, equipos, cerrar). Pueblos con su nombre y color del
	    duenio, zonas (cuadros de tierra pintados por el pueblo mas cercano), equipos (cuadraditos), reloj del juego,
	    pueblos por bando y avisos. Se cierra con CERRAR, ESC o M; borra sus marcadores y devuelve los de la mision.
	    Durante la partida no se ven los equipos ni los avisos de operaciones / apoyo aereo del enemigo (seria
	    informacion); al terminar se ve todo (consola: VIOC_WR_SHOW_ALL = true).
	  - Al terminar la partida (Client_OnMissionEnding, antes de la escena final): la repeticion sola, con boton SALTAR,
	    si VIOC_WAR_REPLAY_END = 1 (espera como mucho VIOC_WR_SPEED + 25 s).
	Parametros de lobby: VIOC_WAR_REPLAY (0/1), VIOC_WAR_REPLAY_END (0/1), VIOC_WAR_REPLAY_SPEED (30/60/120).
	Consola (LOCAL EXEC):
	    hint (call VIOC_WR_fnc_info);          servidor: lo grabado (pueblos, cambios, avisos, fotos, tamanio)
	    [false] spawn VIOC_WR_fnc_open;        abre la repeticion (como la accion)
	    [true] spawn VIOC_WR_fnc_open;         como al terminar la partida (sin pausa, se cierra sola)
	    [120] spawn VIOC_WR_fnc_demo;          prueba de la interfaz con una guerra inventada de 120 min (no graba nada)
	    call VIOC_WR_fnc_saveNow;              servidor: copia al perfil y saveProfileNamespace ya
*/
if (!isNil "VIOC_WR_LOADED") exitWith {};
VIOC_WR_LOADED = true;

//--- Parametros de lobby (en "Un jugador" la mision no los carga: valen los de por defecto).
VIOC_WR_fnc_param = {
	params ["_name", "_def", "_min", "_max"];
	private _v = missionNamespace getVariable [_name, _def];
	if !(_v isEqualType 0) then {_v = _def};
	((round _v) max _min) min _max
};
VIOC_WR_ON = ["VIOC_WAR_REPLAY", 1, 0, 1] call VIOC_WR_fnc_param;
VIOC_WR_END = ["VIOC_WAR_REPLAY_END", 1, 0, 1] call VIOC_WR_fnc_param;
VIOC_WR_SPEED = ["VIOC_WAR_REPLAY_SPEED", 60, 30, 120] call VIOC_WR_fnc_param;
if !(VIOC_WR_SPEED in [30, 60, 120]) then {VIOC_WR_SPEED = 60};

//--- Ajustes
VIOC_WR_TAG = "VIOCWR1";
VIOC_WR_VERSION = "war_replay 2026-10-17";
VIOC_WR_TICK = 5;            //--- s entre lecturas de los pueblos
VIOC_WR_SLOW = 15;           //--- s entre lecturas de HQ, bases, operaciones y apoyo aereo
VIOC_WR_SNAP0 = 120;         //--- s entre fotos de los equipos (se dobla al recortar)
VIOC_WR_SNAP_MAX = 960;      //--- s: intervalo maximo de las fotos
VIOC_WR_MAX_POS = 3000;      //--- posiciones de equipos guardadas como mucho (todas las fotos)
VIOC_WR_MAX_TEAMS = 40;      //--- equipos por bando y foto como mucho
VIOC_WR_MAX_CHG = 4000;      //--- cambios de duenio como mucho (despues se deja de anotar y se marca)
VIOC_WR_MAX_EV = 600;        //--- avisos como mucho (se borran primero los menores: base, so, cas, gs)
VIOC_WR_SAVE_EVERY = 600;    //--- s entre saveProfileNamespace propios (solo si la mision no guarda sola)
VIOC_WR_HIST_MAX = 3;        //--- partidas terminadas que se guardan en el perfil
VIOC_WR_UNIT = 10;           //--- m por unidad en las posiciones de fotos y avisos
VIOC_WR_SEEN_MAX = 300;

//--- Estado (todas las maquinas)
VIOC_WR_PLAYING = false;
VIOC_WR_CL_DATA = [];
VIOC_WR_CL_GOT = -1;
VIOC_WR_MK = [];
VIOC_WR_CTRLS = [];
VIOC_WR_HID = createHashMap;
VIOC_WR_UI_STOP = false;
VIOC_WR_UI_PAUSE = false;
VIOC_WR_UI_RESTART = false;
VIOC_WR_UI_ZONES = true;
VIOC_WR_UI_DOTS = true;
VIOC_WR_UI_DUR = VIOC_WR_SPEED;
if (isNil "VIOC_WR_SHOW_ALL") then {VIOC_WR_SHOW_ALL = false};

if (VIOC_WR_ON <= 0) exitWith {diag_log "[VIOC war_replay] apagado (VIOC_WAR_REPLAY = 0)"};

//=====================================================================================================================
// Comun
//=====================================================================================================================
VIOC_WR_fnc_key = {format ["VIOC_WAR_%1_%2", missionName, worldName]};

//--- numero -> entero en texto (sin notacion cientifica)
VIOC_WR_fnc_i = {(round _this) toFixed 0};

VIOC_WR_fnc_valid = {
	params [["_d", []]];
	(_d isEqualType []) && {count _d >= 7} && {(_d select 0) isEqualTo VIOC_WR_TAG} && {(_d select 1) isEqualType []}
		&& {(_d select 2) isEqualType []} && {(_d select 3) isEqualType ""} && {(_d select 4) isEqualType ""}
		&& {(_d select 5) isEqualType ""} && {(_d select 6) isEqualType []}
};

//--- [s] -> "H:MM:SS"
VIOC_WR_fnc_hms = {
	params ["_s"];
	_s = (round _s) max 0;
	private _h = floor (_s / 3600);
	private _m = floor ((_s mod 3600) / 60);
	private _sec = _s mod 60;
	format ["%1:%2%3:%4%5", _h, ["", "0"] select (_m < 10), _m, ["", "0"] select (_sec < 10), _sec]
};

//--- nombres de los bandos (nation-agnostic: los de la mision si se reconocen; VIOC_WR_SIDE_NAMES los fuerza)
VIOC_WR_fnc_sideNames = {
	if (!isNil "VIOC_WR_SIDE_NAMES" && {VIOC_WR_SIDE_NAMES isEqualType []} && {count VIOC_WR_SIDE_NAMES >= 3}) exitWith {(+VIOC_WR_SIDE_NAMES) select [0, 3]};
	private _res = ["Oeste", "Este", "Guerrilla"];
	{
		private _sid = _x;
		{
			if ((missionNamespace getVariable [_x select 0, -9]) isEqualTo _sid) exitWith {_res set [_sid, _x select 1]};
		} forEach [["CTI_US_SIDE", "EE.UU."], ["CTI_SOV_SIDE", "Rusia"], ["CTI_UKRAIN_SIDE", "Ucrania"], ["CTI_COL_SIDE", "Colombia"],
			["CTI_BW_SIDE", "Alemania"], ["CTI_BAF_SIDE", "Reino Unido"], ["CTI_CDF_SIDE", "Chernarus"], ["CTI_NVA_SIDE", "Vietnam del Norte"],
			["CTI_CHDKZ_SIDE", "ChDKZ"]];
	} forEach [0, 1];
	_res
};

//--- [registro] -> [pueblos, cambios, avisos, fotos, meta, estado, duracion] (o [] si no sirve); listas ya separadas
VIOC_WR_fnc_parse = {
	params [["_d", []]];
	if !([_d] call VIOC_WR_fnc_valid) exitWith {[]};
	private _meta = _d select 1;
	private _u = _meta param [8, 10];
	if !(_u isEqualType 0) then {_u = 10};
	private _towns = ((_d select 2) select {(_x isEqualType []) && {count _x >= 4}}) apply {
		[_x param [0, "?"], _x param [1, 0], _x param [2, 0], _x param [3, -1], _x param [4, 0]]
	};
	private _chg = (((_d select 3) splitString ";") apply {((_x splitString ",") apply {parseNumber _x})}) select {count _x == 3};
	private _evs = (((_d select 4) splitString ";") apply {_x splitString ","}) select {count _x >= 6};
	_evs = _evs apply {[parseNumber (_x select 0), _x select 1, parseNumber (_x select 2), (parseNumber (_x select 3)) * _u, (parseNumber (_x select 4)) * _u, parseNumber (_x select 5)]};
	private _sn = [];
	{
		private _f = _x splitString ",";
		if (count _f >= 4) then {
			private _sides = [];
			for "_k" from 2 to 3 do {
				private _txt = _f select _k;
				private _pts = [];
				if (_txt != "-") then {
					private _v = _txt splitString " ";
					for "_j" from 0 to ((count _v) - 2) step 2 do {
						_pts pushBack [(parseNumber (_v select _j)) * _u, (parseNumber (_v select (_j + 1))) * _u, 0];
					};
				};
				_sides pushBack _pts;
			};
			_sn pushBack [parseNumber (_f select 0), parseNumber (_f select 1), _sides select 0, _sides select 1];
		};
	} forEach ((_d select 5) splitString ";");
	private _st = _d select 6;
	private _span = _st param [0, 0];
	if !(_span isEqualType 0) then {_span = 0};
	if (count _chg > 0) then {_span = _span max ((_chg select ((count _chg) - 1)) select 0)};
	if (count _evs > 0) then {_span = _span max ((_evs select ((count _evs) - 1)) select 0)};
	if (count _sn > 0) then {_span = _span max ((_sn select ((count _sn) - 1)) select 0)};
	[_towns, _chg, _evs, _sn, _meta, _st, _span]
};

//=====================================================================================================================
// Servidor: grabacion
//=====================================================================================================================
VIOC_WR_fnc_now = {(round (time - VIOC_WR_T0)) + VIOC_WR_TOFF};

VIOC_WR_fnc_flag = {
	params ["_b"];
	if (((floor (VIOC_WR_TRUNC / _b)) mod 2) == 0) then {VIOC_WR_TRUNC = VIOC_WR_TRUNC + _b};
};

//--- [tipo, bando, posicion, dato] -> anota un aviso
VIOC_WR_fnc_ev = {
	params ["_kind", ["_sid", -1], ["_pos", [0, 0, 0]], ["_idx", -1]];
	if (VIOC_WR_NEV >= VIOC_WR_MAX_EV) then {call VIOC_WR_fnc_trimEv};
	if !((_pos isEqualType []) && {count _pos >= 2}) then {_pos = [0, 0, 0]};
	if !(_sid isEqualType 0) then {_sid = -1};
	if !(_idx isEqualType 0) then {_idx = -1};
	VIOC_WR_DATA set [4, (VIOC_WR_DATA select 4) + format ["%1,%2,%3,%4,%5,%6;", (call VIOC_WR_fnc_now) call VIOC_WR_fnc_i, _kind,
		_sid call VIOC_WR_fnc_i, ((_pos select 0) / VIOC_WR_UNIT) call VIOC_WR_fnc_i, ((_pos select 1) / VIOC_WR_UNIT) call VIOC_WR_fnc_i, _idx call VIOC_WR_fnc_i]];
	VIOC_WR_NEV = VIOC_WR_NEV + 1;
};

//--- tope de avisos: borra el 10 % (primero los menores; nunca el primero)
VIOC_WR_fnc_trimEv = {
	private _l = (VIOC_WR_DATA select 4) splitString ";";
	private _drop = ceil ((count _l) / 10);
	private _out = [];
	{
		private _k = (_x splitString ",") param [1, ""];
		if ((_drop > 0) && {_k in ["base", "so", "cas", "gs"]}) then {_drop = _drop - 1} else {_out pushBack _x};
	} forEach _l;
	while {(_drop > 0) && {count _out > 1}} do {_out deleteAt 1; _drop = _drop - 1};
	VIOC_WR_DATA set [4, if (count _out == 0) then {""} else {(_out joinString ";") + ";"}];
	VIOC_WR_NEV = count _out;
	[1] call VIOC_WR_fnc_flag;
};

//--- pueblos de aerodromo (la regla de VIOC_airfields / towns_capital: el pueblo en juego mas cercano a 1500 m del ILS)
VIOC_WR_fnc_airfieldTowns = {
	private _w = configFile >> "CfgWorlds" >> worldName;
	private _cfgs = [_w];
	if (isClass (_w >> "SecondaryAirports")) then {_cfgs append ("true" configClasses (_w >> "SecondaryAirports"))};
	private _res = [];
	{
		private _p = getArray (_x >> "ilsPosition");
		if ((count _p >= 2) && {!(((_p select 0) == 0) && {(_p select 1) == 0})}) then {
			private _pt = [_p select 0, _p select 1, 0];
			private _best = objNull;
			private _bd = 1500;
			{
				private _dd = _x distance2D _pt;
				if (_dd < _bd) then {_bd = _dd; _best = _x};
			} forEach VIOC_WR_TOWNS;
			if (!isNull _best) then {_res pushBackUnique _best};
		};
	} forEach _cfgs;
	{_res pushBackUnique _x} forEach ((missionNamespace getVariable ["VIOC_TC_AF_TOWNS", []]) select {(_x isEqualType objNull) && {!isNull _x}});
	_res
};

//--- marcas de los pueblos: 1 capital (towns_capital: vioc_capital), 2 aerodromo
VIOC_WR_fnc_flags = {
	private _af = call VIOC_WR_fnc_airfieldTowns;
	{
		private _f = 0;
		if ((_x getVariable ["vioc_capital", false]) isEqualTo true) then {_f = _f + 1};
		if (_x in _af) then {_f = _f + 2};
		((VIOC_WR_DATA select 2) select _forEachIndex) set [4, _f];
	} forEach VIOC_WR_TOWNS;
	VIOC_WR_FLAGS = (VIOC_WR_DATA select 2) apply {_x select 4};
};

VIOC_WR_fnc_pollTowns = {
	private _t = call VIOC_WR_fnc_now;
	{
		private _s = _x getVariable ["cti_town_sideID", -1];
		if !(_s isEqualType 0) then {_s = -1};
		if (_s != (VIOC_WR_OWN select _forEachIndex)) then {
			VIOC_WR_OWN set [_forEachIndex, _s];
			if (VIOC_WR_NCHG < VIOC_WR_MAX_CHG) then {
				VIOC_WR_DATA set [3, (VIOC_WR_DATA select 3) + format ["%1,%2,%3;", _t call VIOC_WR_fnc_i, _forEachIndex, _s call VIOC_WR_fnc_i]];
				VIOC_WR_NCHG = VIOC_WR_NCHG + 1;
			} else {[2] call VIOC_WR_fnc_flag};
			private _f = VIOC_WR_FLAGS select _forEachIndex;
			if ((_f mod 2) == 1) then {["cap", _s, getPosATL _x, _forEachIndex] call VIOC_WR_fnc_ev};
			if (((floor (_f / 2)) mod 2) == 1) then {["af", _s, getPosATL _x, _forEachIndex] call VIOC_WR_fnc_ev};
		};
	} forEach VIOC_WR_TOWNS;
};

//--- HQ destruido (el objeto sigue y no esta vivo) y edificios de base perdidos (oeste y este)
VIOC_WR_fnc_pollBases = {
	{
		private _side = _x;
		private _i = _forEachIndex;
		private _sid = (_side) call CTI_CO_FNC_GetSideID;
		private _lg = (_side) call CTI_CO_FNC_GetSideLogic;
		if (!isNull _lg) then {
			(VIOC_WR_HQ select _i) params ["_o", "_a", "_p"];
			if ((!isNull _o) && {_a} && {!alive _o}) then {["hq", _sid, _p] call VIOC_WR_fnc_ev};
			private _hq = _lg getVariable ["cti_hq", objNull];
			if !(_hq isEqualType objNull) then {_hq = objNull};
			VIOC_WR_HQ set [_i, [_hq, alive _hq, if (alive _hq) then {getPosATL _hq} else {_p}]];
			private _lost = (VIOC_WR_BASE select _i) select {(isNull (_x select 0)) || {!alive (_x select 0)}};
			if (count _lost > 0) then {["base", _sid, (_lost select 0) select 1, count _lost] call VIOC_WR_fnc_ev};
			private _ss = _lg getVariable ["cti_structures", []];
			if !(_ss isEqualType []) then {_ss = []};
			VIOC_WR_BASE set [_i, (_ss select {(_x isEqualType objNull) && {alive _x} && {!(_x isEqualTo _hq)}}) apply {[_x, getPosATL _x]}];  //--- el HQ desplegado va aparte (aviso "hq")
		};
	} forEach [west, east];
};

//--- [clave] -> true si ya se vio (y la anota si no)
VIOC_WR_fnc_seen = {
	params ["_k"];
	if (_k in VIOC_WR_SEEN) exitWith {true};
	VIOC_WR_SEEN pushBack _k;
	if (count VIOC_WR_SEEN > VIOC_WR_SEEN_MAX) then {VIOC_WR_SEEN deleteAt 0};
	false
};

//--- operaciones especiales (ai_specops / specops_player) y apoyo aereo (air_support), si esos parches estan
VIOC_WR_fnc_pollOps = {
	if (!isNil "VIOC_SO_OPS" && {VIOC_SO_OPS isEqualType []}) then {
		{
			private _sid = [CTI_WEST_ID, CTI_EAST_ID] select (_forEachIndex min 1);
			if (_x isEqualType []) then {
				{
					if (_x isEqualType []) then {
						_x params [["_tok", -1], "", ["_town", objNull, [objNull]]];
						if !([["so", _tok]] call VIOC_WR_fnc_seen) then {
							["so", _sid, if (isNull _town) then {[0, 0, 0]} else {getPosATL _town}, VIOC_WR_TOWNS find _town] call VIOC_WR_fnc_ev;
						};
					};
				} forEach _x;
			};
		} forEach (VIOC_SO_OPS select [0, 2]);
	};
	if (!isNil "VIOC_SO_PREQ" && {VIOC_SO_PREQ isEqualType []}) then {
		{
			if ((_x isEqualType []) && {count _x >= 6}) then {
				_x params ["", ["_tok", -1], "", "", ["_town", objNull, [objNull]], ["_side", sideUnknown, [sideUnknown]]];
				if !([["so", _tok]] call VIOC_WR_fnc_seen) then {
					["so", (_side) call CTI_CO_FNC_GetSideID, if (isNull _town) then {[0, 0, 0]} else {getPosATL _town}, VIOC_WR_TOWNS find _town] call VIOC_WR_fnc_ev;
				};
			};
		} forEach VIOC_SO_PREQ;
	};
	if (!isNil "VIOC_ASS_ACTIVE" && {VIOC_ASS_ACTIVE isEqualType []}) then {
		{
			if (_x isEqualType createHashMap) then {
				private _c = _x getOrDefault ["center", []];
				if ((_c isEqualType []) && {count _c >= 2}) then {
					private _kd = _x getOrDefault ["kind", ""];
					private _sd = _x getOrDefault ["side", sideUnknown];
					if (!([[_kd, _sd, _x getOrDefault ["t0", 0]]] call VIOC_WR_fnc_seen) && {_kd in ["cas", "gs"]}) then {
						[_kd, (_sd) call CTI_CO_FNC_GetSideID, _c] call VIOC_WR_fnc_ev;
					};
				};
			};
		} forEach VIOC_ASS_ACTIVE;
	};
};

//--- foto de los jefes de equipo de oeste y este
VIOC_WR_fnc_snap = {
	private _parts = [];
	private _np = 0;
	{
		private _lg = (_x) call CTI_CO_FNC_GetSideLogic;
		private _teams = if (isNull _lg) then {[]} else {_lg getVariable ["cti_teams", []]};
		if !(_teams isEqualType []) then {_teams = []};
		private _pts = [];
		{
			if !(isNil "_x") then {
				if ((_x isEqualType grpNull) && {!isNull _x} && {(count _pts) < (2 * VIOC_WR_MAX_TEAMS)}) then {
					private _ld = leader _x;
					if (alive _ld) then {
						private _p = getPosATL (vehicle _ld);
						_pts pushBack ((_p select 0) / VIOC_WR_UNIT);
						_pts pushBack ((_p select 1) / VIOC_WR_UNIT);
					};
				};
			};
		} forEach _teams;
		_np = _np + floor ((count _pts) / 2);
		_parts pushBack (if (count _pts == 0) then {"-"} else {(_pts apply {_x call VIOC_WR_fnc_i}) joinString " "});
	} forEach [west, east];
	VIOC_WR_DATA set [5, (VIOC_WR_DATA select 5) + format ["%1,%2,%3,%4;", (call VIOC_WR_fnc_now) call VIOC_WR_fnc_i,
		((floor (dayTime * 60)) min 1439) call VIOC_WR_fnc_i, _parts select 0, _parts select 1]];
	VIOC_WR_NPOS = VIOC_WR_NPOS + _np;
	if (VIOC_WR_NPOS > VIOC_WR_MAX_POS) then {call VIOC_WR_fnc_thin};
};

//--- tope de posiciones: borra una foto de cada dos (conserva la ultima) y dobla el intervalo
