VIOC_WR_fnc_srvMain = {
	waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Init_Server"}};
	waitUntil {sleep 2; ({isNil {_x getVariable "cti_town_sideID"}} count CTI_Towns) == 0};
	sleep 5;
	if (missionNamespace getVariable ["CTI_GameOver", false]) exitWith {};
	VIOC_WR_TOWNS = +CTI_Towns;
	VIOC_WR_OVER = false;
	VIOC_WR_WINNER = -1;
	VIOC_WR_SYS_END = [];
	VIOC_WR_DATE_END = [];
	VIOC_WR_SEEN = [];
	VIOC_WR_NPOS = 0;
	VIOC_WR_NCHG = 0;
	VIOC_WR_NEV = 0;
	VIOC_WR_TRUNC = 0;
	VIOC_WR_SNAPINT = VIOC_WR_SNAP0;
	VIOC_WR_TOFF = 0;
	VIOC_WR_T0 = time;
	private _key = call VIOC_WR_fnc_key;
	private _names = VIOC_WR_TOWNS apply {_x getVariable ["cti_town_name", "?"]};
	private _old = profileNamespace getVariable [_key, []];
	private _resume = false;
	if (([_old] call VIOC_WR_fnc_valid) && {((_old select 6) param [1, 1]) isEqualTo 0}) then {
		//--- partida grabada sin terminar: se continua si la mision cargo su guardado y son los mismos pueblos
		private _same = ((_old select 2) apply {_x param [0, ""]}) isEqualTo _names;
		private _loaded = ((missionNamespace getVariable ["CTI_PERSISTANT", 0]) isEqualType 0) && {(missionNamespace getVariable ["CTI_PERSISTANT", 0]) > 0}
			&& {!isNil "CTI_SE_FNC_LOAD"} && {(["exists"] call CTI_SE_FNC_LOAD) isEqualTo true}
			&& {!(((_old select 6) param [10, 1]) isEqualTo 0)};  //--- no reanudar una grabacion hecha con PERSIST apagado (la mision no la guardo)
		if (_same && {_loaded}) then {_resume = true} else {
			if ((((_old select 6) param [0, 0]) isEqualType 0) && {((_old select 6) param [0, 0]) >= 300}) then {[_old] call VIOC_WR_fnc_archive};
			profileNamespace setVariable [_key, nil];
		};
	};
	isNil {
		if (_resume) then {
			VIOC_WR_DATA = +_old;
			private _st = _old select 6;
			VIOC_WR_TOFF = (_st param [0, 0]) + 30;
			VIOC_WR_NPOS = _st param [5, 0];
			VIOC_WR_NCHG = _st param [6, 0];
			VIOC_WR_NEV = _st param [7, 0];
			VIOC_WR_TRUNC = _st param [8, 0];
			VIOC_WR_SNAPINT = ((_st param [9, VIOC_WR_SNAP0]) max VIOC_WR_SNAP0) min VIOC_WR_SNAP_MAX;
			VIOC_WR_OWN = (VIOC_WR_DATA select 2) apply {_x param [3, -1]};
			{
