				if ((count _f == 3) && {(_f select 1) >= 0} && {(_f select 1) < count VIOC_WR_OWN}) then {VIOC_WR_OWN set [_f select 1, _f select 2]};
			} forEach ((VIOC_WR_DATA select 3) splitString ";");
			["resume"] call VIOC_WR_fnc_ev;
		} else {
			private _meta = [missionName, worldName, worldSize, briefingName, systemTime, date, call VIOC_WR_fnc_sideNames, VIOC_WR_VERSION, VIOC_WR_UNIT];
			private _towns = VIOC_WR_TOWNS apply {
				private _p = getPosATL _x;
				private _s = _x getVariable ["cti_town_sideID", -1];
				if !(_s isEqualType 0) then {_s = -1};
				[_x getVariable ["cti_town_name", "?"], round (_p select 0), round (_p select 1), _s, 0]
			};
			VIOC_WR_DATA = [VIOC_WR_TAG, _meta, _towns, "", "", "", []];
			VIOC_WR_OWN = _towns apply {_x select 3};
