		VIOC_WR_BASE = [[], []];
		call VIOC_WR_fnc_flags;
		call VIOC_WR_fnc_pollBases;
		call VIOC_WR_fnc_pollTowns;
		call VIOC_WR_fnc_status;
		VIOC_WR_READY = true;
	};
	diag_log format ["[VIOC war_replay] graba %1 (%2 pueblos, %3; fotos cada %4 s; repeticion %5 s, al final %6; la mision guarda sola: %7)",
		_key, count VIOC_WR_TOWNS, ["partida nueva", "continua la partida guardada"] select _resume, VIOC_WR_SNAPINT, VIOC_WR_SPEED, VIOC_WR_END, call VIOC_WR_fnc_missionSaves];
	private _nSlow = time + VIOC_WR_SLOW;
	private _nSnap = time + 10;
	private _nSave = time + VIOC_WR_SAVE_EVERY;
	private _nFlags = [time + 90, time + 300];
	private _overSeen = -1;
	while {!VIOC_WR_OVER} do {
		sleep VIOC_WR_TICK;
		if (VIOC_WR_OVER) exitWith {};
		isNil {
			call VIOC_WR_fnc_pollTowns;
			if (time > _nSlow) then {_nSlow = time + VIOC_WR_SLOW; call VIOC_WR_fnc_pollBases; call VIOC_WR_fnc_pollOps};
			if ((count _nFlags > 0) && {time > (_nFlags select 0)}) then {_nFlags deleteAt 0; call VIOC_WR_fnc_flags};
			if (time > _nSnap) then {_nSnap = time + VIOC_WR_SNAPINT; call VIOC_WR_fnc_snap; if !(call VIOC_WR_fnc_missionSaves) then {[false] call VIOC_WR_fnc_persist}};
		};
