		if ((missionNamespace getVariable ["CTI_GameOver", false]) && {!VIOC_WR_OVER}) then {
			if (_overSeen < 0) then {_overSeen = time} else {if (time > _overSeen + 8) then {[sideUnknown] call VIOC_WR_fnc_gameOver}};
		};
	};
};

