//--- [auto (fin de partida), registro opcional] (con spawn). Abre el mapa y repite la guerra.
VIOC_WR_fnc_open = {
	params [["_auto", false], ["_rec", []]];
	if (!hasInterface || {VIOC_WR_PLAYING}) exitWith {};
	VIOC_WR_PLAYING = true;
	VIOC_WR_UI_STOP = false;
	VIOC_WR_UI_PAUSE = false;
	VIOC_WR_UI_RESTART = false;
	VIOC_WR_UI_DUR = VIOC_WR_SPEED;
	if !([_rec] call VIOC_WR_fnc_valid) then {
		if (!_auto && {!isServer}) then {hintSilent "Historia de la guerra: cargando..."};
		_rec = call VIOC_WR_fnc_getData;
	};
	private _P = [_rec] call VIOC_WR_fnc_parse;
	if (count _P == 0) exitWith {
		VIOC_WR_PLAYING = false;
		if (!_auto) then {hint "Historia de la guerra: todavia no hay nada grabado (empieza al minuto de partida)."};
	};
	_P params ["_towns", "_chg", "_evs", "_sn", "_meta", "_st", "_span"];
	private _nt = count _towns;
	if ((_span < 30) || {_nt == 0}) exitWith {
		VIOC_WR_PLAYING = false;
		if (!_auto) then {hint "Historia de la guerra: todavia es muy corta (vuelve en unos minutos)."};
	};
	private _over = (((_st param [1, 0]) isEqualTo 1) || {missionNamespace getVariable ["CTI_GameOver", false]});
	private _all = _over || {VIOC_WR_SHOW_ALL isEqualTo true};
	private _my = missionNamespace getVariable ["CTI_P_SideID", -1];
	private _names = _meta param [6, ["Oeste", "Este", "Guerrilla"]];
	if !((_names isEqualType []) && {count _names >= 3}) then {_names = ["Oeste", "Este", "Guerrilla"]};
	private _ws = _meta param [2, worldSize];
	if !(_ws isEqualType 0) then {_ws = worldSize};
	private _title = _meta param [3, missionName];
	if !(_title isEqualType "") then {_title = missionName};
	_title = (_title splitString "<>&") joinString " ";
	private _colM = {if (_this in [0, 1, 2]) then {["ColorBlue", "ColorRed", "ColorGreen"] select _this} else {"ColorGrey"}};
	private _colH = {if (_this in [0, 1, 2]) then {["#5b9cff", "#ff6060", "#5bd16a"] select _this} else {"#b0b0b0"}};
	private _sname = {if (_this in [0, 1, 2]) then {((_names select _this) splitString "<>&") joinString " "} else {"?"}};
	private _cidx = {if (_this in [0, 1, 2]) then {_this} else {3}};
	private _tname = {(((_towns select _this) select 0) splitString "<>&") joinString " "};
	private _nearName = {
		params ["_qx", "_qy"];
		private _bi = -1;
		private _bd = 1e12;
		{
			private _dd = (((_x select 1) - _qx) ^ 2) + (((_x select 2) - _qy) ^ 2);
			if (_dd < _bd) then {_bd = _dd; _bi = _forEachIndex};
		} forEach _towns;
