	};
	//--- reloj del juego: [t, minutos acumulados desde la medianoche del primer dia] (fotos + inicio)
	private _date0 = _meta param [5, []];
	private _clk = [];
	private _acc = 0;
	private _prev = -1;
	if ((_date0 isEqualType []) && {count _date0 >= 5}) then {_prev = ((_date0 select 3) * 60) + (_date0 select 4); _clk pushBack [0, _prev]};
	{
		private _dm = _x select 1;
		if ((_prev >= 0) && {_dm < (_prev - 30)}) then {_acc = _acc + 1440};
		_prev = _dm;
		_clk pushBack [_x select 0, _dm + _acc];
	} forEach _sn;

	for "_i" from 1 to 5 do {if (dialog) then {closeDialog 0}};
	if (_auto && {visibleMap}) then {openMap false; sleep 0.5};  //--- al terminar: cierra otro panel VIOC de mapa que estuviera abierto
	if (!visibleMap) then {openMap [true, false]};
