	call VIOC_WR_fnc_hideOthers;

	//--- vista: todos los pueblos (el panel tapa la parte de arriba)
	private _bx0 = 1e9; private _bx1 = -1e9; private _by0 = 1e9; private _by1 = -1e9;
	{
