		_by0 = _by0 min (_x select 2); _by1 = _by1 max (_x select 2);
	} forEach _towns;
	_bx0 = _bx0 - 1000; _bx1 = _bx1 + 1000; _by0 = _by0 - 1000; _by1 = _by1 + 1000;
	private _cen = [(_bx0 + _bx1) / 2, ((_by0 + _by1) / 2) + ((_by1 - _by0) * 0.07), 0];
	_ctrl ctrlMapAnimAdd [0, 0.3, _cen];
