	sleep 0.25;
	private _pa = _ctrl ctrlMapScreenToWorld [safeZoneX, safeZoneY];
	private _pb = _ctrl ctrlMapScreenToWorld [safeZoneX + safeZoneW, safeZoneY + safeZoneH];
	private _vw = abs ((_pb select 0) - (_pa select 0));
	private _vh = abs ((_pa select 1) - (_pb select 1));
