		deleteMarkerLocal _m;
		createMarkerLocal [_m, [0, 0, 0]];
		_m setMarkerShapeLocal "ELLIPSE";
		_m setMarkerBrushLocal "Border";
		_m setMarkerAlphaLocal 0;
		_fx pushBack [_m, -100];
		VIOC_WR_MK pushBack _m;
	};
	private _fxi = 0;
	private _flash = {
