	private _btn = {
		params ["_pos", "_txt", "_code"];
		private _b = ["RscButton", _pos] call _mk;
		_b ctrlSetText _txt;
		_b ctrlAddEventHandler ["ButtonClick", _code];
		_b
	};
	private _W = safeZoneW;
	private _H = safeZoneH;
	private _x0 = safeZoneX + _W * 0.17;
	private _y0 = safeZoneY + _H * 0.012;
	private _pw = _W * 0.66;  //--- no _w: en SQF _w y _W son la misma variable
	private _p = _W * 0.004;
	private _lh = _H * 0.03;
	private _iw = _pw - 2 * _p;
	private _hAll = _p + _lh * 2.3 + _p + _lh * 0.45 + _p + _lh * 0.3 + _p + _lh * 1.1 + _p;
	private _bg = ["RscText", [_x0, _y0, _pw, _hAll]] call _mk;
	_bg ctrlSetBackgroundColor [0, 0, 0, 0.78];
	private _y = _y0 + _p;
	private _info = ["RscStructuredText", [_x0 + _p, _y, _iw, _lh * 2.3]] call _mk;
	_y = _y + _lh * 2.3 + _p;
	private _dom = [];
	{
		private _c = ["RscText", [_x0 + _p, _y, 0.001, _lh * 0.45]] call _mk;
		_c ctrlSetBackgroundColor _x;
		_dom pushBack _c;
	} forEach [[0.25, 0.5, 1, 0.95], [0.95, 0.3, 0.3, 0.95], [0.3, 0.8, 0.35, 0.95], [0.55, 0.55, 0.55, 0.9]];
	private _yDom = _y;
	_y = _y + _lh * 0.45 + _p;
	private _pbg = ["RscText", [_x0 + _p, _y, _iw, _lh * 0.3]] call _mk;
	_pbg ctrlSetBackgroundColor [1, 1, 1, 0.15];
	private _pfg = ["RscText", [_x0 + _p, _y, 0.001, _lh * 0.3]] call _mk;
	_pfg ctrlSetBackgroundColor [1, 0.82, 0.5, 0.95];
	private _yPro = _y;
	_y = _y + _lh * 0.3 + _p;
	private _bdef = if (_auto) then {
		[["ZONAS", "with missionNamespace do {VIOC_WR_UI_ZONES = !VIOC_WR_UI_ZONES}"], ["EQUIPOS", "with missionNamespace do {VIOC_WR_UI_DOTS = !VIOC_WR_UI_DOTS}"],
			["SALTAR", "with missionNamespace do {VIOC_WR_UI_STOP = true}"]]
	} else {
		[["30 s", "with missionNamespace do {VIOC_WR_UI_DUR = 30}"], ["60 s", "with missionNamespace do {VIOC_WR_UI_DUR = 60}"],
			["120 s", "with missionNamespace do {VIOC_WR_UI_DUR = 120}"], ["PAUSA", "with missionNamespace do {VIOC_WR_UI_PAUSE = !VIOC_WR_UI_PAUSE}"],
			["REINICIAR", "with missionNamespace do {VIOC_WR_UI_RESTART = true}"], ["ZONAS", "with missionNamespace do {VIOC_WR_UI_ZONES = !VIOC_WR_UI_ZONES}"],
			["EQUIPOS", "with missionNamespace do {VIOC_WR_UI_DOTS = !VIOC_WR_UI_DOTS}"], ["CERRAR", "with missionNamespace do {VIOC_WR_UI_STOP = true}"]]
	};
	private _nb = count _bdef;
	private _bw = (_iw - (_nb - 1) * _p) / _nb;
	private _btns = [];
	{
		_btns pushBack ([[_x0 + _p + _forEachIndex * (_bw + _p), _y, _bw, _lh * 1.1], _x select 0, _x select 1] call _btn);
	} forEach _bdef;
	private _cap = ["RscStructuredText", [safeZoneX + _W * 0.01, safeZoneY + _H * 0.70, _W * 0.36, _H * 0.25]] call _mk;
	_cap ctrlSetBackgroundColor [0, 0, 0, 0.55];
	if (isNull _info) exitWith {
		call VIOC_WR_fnc_cleanup;
		VIOC_WR_PLAYING = false;
		if (visibleMap) then {openMap false};
		hint "Historia de la guerra: no se pudo crear el panel del mapa.";
	};

	//--- estado de la repeticion
	private _cnt = [0, 0, 0, 0];
	{_cnt set [_x call _cidx, (_cnt select (_x call _cidx)) + 1]} forEach _own;
	private _tr = 0;
	private _pc = 0;
	private _pe = 0;
	private _ps = -1;
	private _pk = 0;
	private _caps = [];
	private _last = diag_tickTime;
	private _nextUi = 0;
	private _nextHide = diag_tickTime + 1;
	private _endAt = -1;
	private _deadline = diag_tickTime + VIOC_WR_SPEED + 12;
	private _zonesOn = VIOC_WR_UI_ZONES;
	private _dotsOn = VIOC_WR_UI_DOTS;
	private _dirtyDots = false;
	private _nchg = count _chg;
	private _nevs = count _evs;
	private _nsn = count _sn;
	private _done = false;
	private _evText = {
		params ["_e"];
		_e params ["", "_k", "_s", "_ex", "_ey", "_ei"];
		private _sn2 = format ["<t color='%1'>%2</t>", _s call _colH, _s call _sname];
		private _tn = if ((_ei >= 0) && {_ei < _nt}) then {_ei call _tname} else {[_ex, _ey] call _nearName};
		switch (_k) do {
			case "cap": {format ["%1 toma la CAPITAL, %2", _sn2, _tn]};
			case "af": {format ["%1 toma un aerodromo: %2", _sn2, _tn]};
			case "hq": {format ["Destruido el cuartel general (HQ) de %1", _sn2]};
			case "base": {format ["%1 pierde %2 edificio(s) de su base", _sn2, _ei]};
			case "so": {format ["Operacion especial de %1 hacia %2", _sn2, _tn]};
			case "cas": {format ["Ataque A-10 de %1 cerca de %2", _sn2, [_ex, _ey] call _nearName]};
			case "gs": {format ["Canonero Ghostrider de %1 sobre %2", _sn2, [_ex, _ey] call _nearName]};
			case "start": {"Empieza la guerra"};
			case "resume": {"Partida reanudada desde el guardado"};
			case "end": {if (_s in [0, 1, 2]) then {format ["FIN DE LA GUERRA: gana %1", _sn2]} else {"FIN DE LA PARTIDA"}};
			default {""};
		}
	};

	while {!_done} do {
		sleep 0.05;
		private _now = diag_tickTime;
		private _dt = (_now - _last) min 0.5;
		_last = _now;
		if (!visibleMap || {VIOC_WR_UI_STOP} || {!_auto && {!alive player}}) then {_done = true};
		if (_auto && {_now > _deadline}) then {_done = true};
		if (!_done) then {
			if (VIOC_WR_UI_RESTART) then {
				VIOC_WR_UI_RESTART = false;
				_tr = 0; _pc = 0; _pe = 0; _ps = -1; _pk = 0; _caps = []; _endAt = -1;
				_own = _towns apply {_x select 3};
				_cnt = [0, 0, 0, 0];
				{_cnt set [_x call _cidx, (_cnt select (_x call _cidx)) + 1]} forEach _own;
				{
					private _cm = (_own select _forEachIndex) call _colM;
					(_mkT select _forEachIndex) setMarkerColorLocal _cm;
					{_x setMarkerColorLocal _cm} forEach _x;
				} forEach _cellsOf;
				_dirtyDots = true;
				_cap ctrlSetStructuredText parseText "";
			};
			if (!VIOC_WR_UI_PAUSE && {_tr < _span}) then {_tr = (_tr + _dt * _span / (VIOC_WR_UI_DUR max 5)) min _span};
			//--- cambios de duenio
			while {(_pc < _nchg) && {((_chg select _pc) select 0) <= _tr}} do {
				(_chg select _pc) params ["", "_ti", "_ts"];
				if ((_ti >= 0) && {_ti < _nt}) then {
					private _o = _own select _ti;
					_own set [_ti, _ts];
					_cnt set [_o call _cidx, ((_cnt select (_o call _cidx)) - 1) max 0];
					_cnt set [_ts call _cidx, (_cnt select (_ts call _cidx)) + 1];
					private _cm = _ts call _colM;
					(_mkT select _ti) setMarkerColorLocal _cm;
					{_x setMarkerColorLocal _cm} forEach (_cellsOf select _ti);
					[[(_towns select _ti) select 1, (_towns select _ti) select 2, 0], "ColorWhite"] call _flash;
				};
				_pc = _pc + 1;
			};
			//--- avisos
			while {(_pe < _nevs) && {((_evs select _pe) select 0) <= _tr}} do {
				private _e = _evs select _pe;
				_e params ["_et", "_ek", "_es", "_ex", "_ey"];
				if (_all || {!(_ek in ["so", "cas", "gs"])} || {_es == _my}) then {
					private _txt = [_e] call _evText;
					if (_txt != "") then {
						_caps = [format ["<t color='#ffd27f'>[%1]</t> %2", [_et] call VIOC_WR_fnc_hms, _txt]] + _caps;
						if (count _caps > 6) then {_caps resize 6};
						_cap ctrlSetStructuredText parseText ("<t size='0.9'>" + (_caps joinString "<br/>") + "</t>");
						if (!((_ek in ["start", "resume", "end"])) && {(_ex > 0) || {_ey > 0}}) then {
							[[_ex, _ey, 0], ["ColorOrange", "ColorYellow"] select (_ek in ["cap", "af"])] call _flash;
						};
					};
				};
				_pe = _pe + 1;
			};
			//--- fotos de los equipos
			while {((_ps + 1) < _nsn) && {((_sn select (_ps + 1)) select 0) <= _tr}} do {_ps = _ps + 1; _dirtyDots = true};
			if (!(_dotsOn isEqualTo VIOC_WR_UI_DOTS)) then {_dotsOn = VIOC_WR_UI_DOTS; _dirtyDots = true};
			if (_dirtyDots) then {
				_dirtyDots = false;
				private _k = 0;
				if (_dotsOn && {_ps >= 0}) then {
					private _sp = _sn select _ps;
					{
						private _sd = _x;
						if (_all || {_sd == _my}) then {
							{
								if (_k >= count _mkD) then {
									private _m = format ["vioc_wr_d%1", _k];
									deleteMarkerLocal _m;
									createMarkerLocal [_m, _x];
									_m setMarkerShapeLocal "ICON";
									_m setMarkerTypeLocal "mil_box";
									_m setMarkerSizeLocal [0.42, 0.42];
									_mkD pushBack _m;
									VIOC_WR_MK pushBack _m;
								};
								private _m = _mkD select _k;
								_m setMarkerPosLocal _x;
								_m setMarkerColorLocal (["ColorWEST", "ColorEAST"] select _sd);
								_m setMarkerAlphaLocal 0.95;
								_k = _k + 1;
							} forEach (_sp select (2 + _sd));
						};
					} forEach [0, 1];
				};
				for "_j" from _k to ((count _mkD) - 1) do {(_mkD select _j) setMarkerAlphaLocal 0};
			};
			//--- zonas encendidas / apagadas
			if (!(_zonesOn isEqualTo VIOC_WR_UI_ZONES)) then {
				_zonesOn = VIOC_WR_UI_ZONES;
				{{_x setMarkerAlphaLocal (if (_zonesOn) then {0.32} else {0})} forEach _x} forEach _cellsOf;
			};
			//--- destellos
			{
				private _age = _now - (_x select 1);
				if (_age < 1.4) then {
					private _r = 150 + 850 * (_age / 1.4);
					(_x select 0) setMarkerSizeLocal [_r, _r];
					(_x select 0) setMarkerAlphaLocal (1 - (_age / 1.4));
				} else {
					if ((_x select 1) > -50) then {(_x select 0) setMarkerAlphaLocal 0; _x set [1, -100]};
				};
			} forEach _fx;
			//--- texto, barra de dominio y progreso
			if (_now > _nextUi) then {
				_nextUi = _now + 0.2;
				while {((_pk + 1) < count _clk) && {((_clk select (_pk + 1)) select 0) <= _tr}} do {_pk = _pk + 1};
				private _clock = "";
				if (count _clk > 0) then {
					private _c0 = _clk select _pk;
					private _mm = _c0 select 1;
					if (((_pk + 1) < count _clk) && {(_c0 select 0) <= _tr}) then {
						private _c1 = _clk select (_pk + 1);
						private _f = ((_tr - (_c0 select 0)) / (((_c1 select 0) - (_c0 select 0)) max 1)) min 1;
						_mm = _mm + ((_c1 select 1) - _mm) * (_f max 0);
					};
					private _day = (floor (_mm / 1440)) + 1;
					private _hm = (floor _mm) mod 1440;
					private _hh = floor (_hm / 60);
					private _mi = _hm mod 60;
					_clock = format ["Dia %1  %2%3:%4%5", _day, ["", "0"] select (_hh < 10), _hh, ["", "0"] select (_mi < 10), _mi];
				};
				private _state = if (_tr >= _span) then {"  (fin)"} else {if (VIOC_WR_UI_PAUSE) then {"  (pausa)"} else {""}};
				_info ctrlSetStructuredText parseText format [
					"<t size='1.05' color='#ffd27f'>HISTORIA DE LA GUERRA</t><t size='0.85' color='#bbbbbb'>   %1 (%2)</t><t align='right' size='0.9'>%3   |   partida %4 / %5%6</t><br/>" +
					"<t size='0.95' color='%7'>%8: %9</t>   <t size='0.95' color='%10'>%11: %12</t>   <t size='0.95' color='%13'>%14: %15</t>   <t size='0.95' color='#b0b0b0'>sin duenio: %16</t>" +
					"<t align='right' size='0.8' color='#aaaaaa'>pueblos de %17   |   repeticion en %18 s%19</t>",
					_title, worldName, _clock, [_tr] call VIOC_WR_fnc_hms, [_span] call VIOC_WR_fnc_hms, _state,
					0 call _colH, 0 call _sname, _cnt select 0, 1 call _colH, 1 call _sname, _cnt select 1, 2 call _colH, 2 call _sname, _cnt select 2,
					_cnt select 3, _nt, VIOC_WR_UI_DUR, if (_all) then {""} else {"   |   enemigo oculto hasta el final"}];
				private _xx = _x0 + _p;
				{
					private _ww = (_iw * (_x / (_nt max 1))) max 0.0001;
					(_dom select _forEachIndex) ctrlSetPosition [_xx, _yDom, _ww, _lh * 0.45];
					(_dom select _forEachIndex) ctrlCommit 0;
					_xx = _xx + _ww;
				} forEach _cnt;
				_pfg ctrlSetPosition [_x0 + _p, _yPro, (_iw * (_tr / (_span max 1))) max 0.0001, _lh * 0.3];
				_pfg ctrlCommit 0;
				if (!_auto) then {
					{
						(_btns select _forEachIndex) ctrlSetBackgroundColor (if (VIOC_WR_UI_DUR == _x) then {[0.75, 0.55, 0.2, 1]} else {[0, 0, 0, 0.8]});
					} forEach [30, 60, 120];
					(_btns select 3) ctrlSetText (if (VIOC_WR_UI_PAUSE) then {"SEGUIR"} else {"PAUSA"});
				};
			};
			if (_now > _nextHide) then {_nextHide = _now + 1; call VIOC_WR_fnc_hideOthers};
			if (_tr >= _span) then {
				if (_endAt < 0) then {_endAt = _now};
				if (_auto && {_now > _endAt + 5}) then {_done = true};
			};
		};
	};
	call VIOC_WR_fnc_cleanup;
	if (visibleMap && {_auto || {VIOC_WR_UI_STOP}}) then {openMap false};
	VIOC_WR_UI_STOP = false;
	VIOC_WR_PLAYING = false;
};

//--- Gancho de Client_OnMissionEnding.sqf (despues de CTI_GameOver = true): la repeticion antes de la escena final.
VIOC_WR_fnc_endHook = {
	if (!hasInterface || {VIOC_WR_END <= 0}) exitWith {};
	if (!canSuspend) exitWith {[true] spawn VIOC_WR_fnc_open};
	if (VIOC_WR_PLAYING) then {
		VIOC_WR_UI_STOP = true;
		private _t0 = diag_tickTime + 3;
		waitUntil {sleep 0.1; !VIOC_WR_PLAYING || {diag_tickTime > _t0}};
	};
	player allowDamage false; (vehicle player) allowDamage false;  //--- la partida ya termino: que no lo maten mientras ve la repeticion
	private _h = [true] spawn VIOC_WR_fnc_open;
	private _t = diag_tickTime + VIOC_WR_SPEED + 25;
	waitUntil {sleep 0.2; (scriptDone _h) || {diag_tickTime > _t}};
	if !(scriptDone _h) then {VIOC_WR_UI_STOP = true; sleep 0.5};
	if (visibleMap) then {openMap false};
};

//--- Prueba de la interfaz (consola, cliente): guerra inventada de _mins minutos con los pueblos de la mision. No graba.
VIOC_WR_fnc_demo = {
	params [["_mins", 120]];
	if (!hasInterface) exitWith {};
	if (isNil "CTI_Towns" || {count CTI_Towns == 0}) exitWith {hint "VIOC war_replay: no hay pueblos todavia"};
	private _towns = CTI_Towns apply {
		private _p = getPosATL _x;
		private _s = _x getVariable ["cti_town_sideID", 2];
		if !(_s isEqualType 0) then {_s = 2};
		[_x getVariable ["cti_town_name", "?"], round (_p select 0), round (_p select 1), _s, [0, 1] select ((_x getVariable ["vioc_capital", false]) isEqualTo true)]
	};
	private _own = _towns apply {_x select 3};
	private _chg = "";
	private _evs = "0,start,-1,0,0,-1;";
	private _sns = "";
	private _T = (_mins max 10) * 60;
	for "_t" from 60 to _T step 75 do {
		private _s = selectRandom [0, 1, 0, 1, 2];
		private _bi = -1;
		private _bd = 1e12;
		{
			if ((_own select _forEachIndex) != _s) then {
				private _tp = _x;
				private _dmin = 1e12;
				{
					if ((_own select _forEachIndex) == _s) then {_dmin = _dmin min ((((_x select 1) - (_tp select 1)) ^ 2) + (((_x select 2) - (_tp select 2)) ^ 2))};
				} forEach _towns;
				_dmin = _dmin * (0.6 + random 0.8);
				if (_dmin < _bd) then {_bd = _dmin; _bi = _forEachIndex};
			};
		} forEach _towns;
		if (_bi >= 0) then {
			_own set [_bi, _s];
			_chg = _chg + format ["%1,%2,%3;", _t, _bi, _s];
			if ((((_towns select _bi) select 4) mod 2) == 1) then {
				_evs = _evs + format ["%1,cap,%2,%3,%4,%5;", _t, _s, round (((_towns select _bi) select 1) / 10), round (((_towns select _bi) select 2) / 10), _bi];
			};
		};
		if ((_t mod 600) < 75) then {
			private _parts = [];
			{
				private _sd = _x;
				private _mine = _towns select {(_own select (_towns find _x)) == _sd};
				private _pts = [];
				for "_k" from 1 to (6 min (count _mine)) do {
					private _tw = selectRandom _mine;
					_pts pushBack (round (((_tw select 1) + (random 600) - 300) / 10));
					_pts pushBack (round (((_tw select 2) + (random 600) - 300) / 10));
				};
				_parts pushBack (if (count _pts == 0) then {"-"} else {(_pts apply {str _x}) joinString " "});
			} forEach [0, 1];
			_sns = _sns + format ["%1,%2,%3,%4;", _t, ((floor (dayTime * 60)) + floor (_t / 60)) mod 1440, _parts select 0, _parts select 1];
		};
	};
	_evs = _evs + format ["%1,end,-1,0,0,-1;", _T];
	private _rec = [VIOC_WR_TAG, [missionName, worldName, worldSize, "PRUEBA (guerra inventada)", systemTime, date, ["Oeste", "Este", "Guerrilla"], VIOC_WR_VERSION, 10],
		_towns, _chg, _evs, _sns, [_T, 1, -1, [], [], 0, 0, 0, 0, 600]];
	[false, _rec] spawn VIOC_WR_fnc_open;
};

